// 创建一个 axios 实例
import axios from 'axios';
import { tansParams, blobValidate } from "@/utils/publicMethods";
const service = axios.create({
  // baseURL: 'http://127.0.0.1:9082', // url = base url + request url
  baseURL: '/text',
  // withCredentials: true, // 发送跨域请求时携带凭证信息（cookies）
  timeout: 20000, // 请求超时时间
  headers: {
    'Content-Type': 'application/json'
    // 可以在这里添加统一的请求头
  }
});
// 请求拦截器
service.interceptors.request.use(
  config => {
    // config.headers.Authorization ='bearer '+ 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..LNfja5heO5kWtQ3kfB-C3lqaUhMoAp1RfbyCCBRKDMw'
    config.headers.Authorization ='bearer '+ 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..e2SAv5bDfZqd7KZSZqqNO158NUKqmTSKGyZ1OadGyqk'

    return config;
  },
  error => {
    // 对请求错误做些什么
    console.log(error); // for debug
    return Promise.reject(error);
  }
);

// 响应拦截器
service.interceptors.response.use(
  response => {
    // 对响应数据做点什么
    return response.data;
  },
  error => {
    // 对响应错误做点什么
    console.log('err' + error); // for debug
    return Promise.reject(error);
  }
);

export default service;
